mod = 1000000007

def solve(n):
	visited = [False] * (n + 1)
	pos = []
	for i in range(0, n + 1, 2):
		pos.append(i)
	for i in range(1, n + 1, 2):
		pos.append(i)
	count = 0
	for i in range(1, n + 1):
		if not visited[i]:
			count += 1
			while not visited[i]:
				visited[i] = True
				i = pos[i]
	print(pow(26, count, mod))
for i in range(int(input())):
	n = int(input())
	solve(n)
